    'Email address': { es: 'Dirección de email', fr: 'Adresse e-mail', pt: 'Endereço de e-mail', de: 'E-Mail-Adresse', it: 'Indirizzo email', ja: 'メールアドレス', ko: '이메일 주소', zh: '邮箱地址' },
    'Your email…': { es: 'Tu email…', fr: 'Ton e-mail…', pt: 'Seu e-mail…', de: 'Deine E-Mail…', it: 'La tua email…', ja: 'メールアドレス…', ko: '이메일 주소…', zh: '你的邮箱…' },
    'Please enter a valid email address.': { es: 'Introduce un email válido.', fr: 'Saisis une adresse e-mail valide.', pt: 'Digite um e-mail válido.', de: 'Bitte gib eine gültige E-Mail-Adresse ein.', it: 'Inserisci un indirizzo email valido.', ja: '有効なメールアドレスを入力してください。', ko: '올바른 이메일 주소를 입력하세요.', zh: '请输入有效的邮箱地址。' },
    'Joining…': { es: 'Uniéndote…', fr: 'Inscription…', pt: 'Entrando…', de: 'Wird angemeldet…', it: 'Iscrizione…', ja: '登録中…', ko: '구독 중…', zh: '订阅中…' },
    'Something went wrong. Please try again.': { es: 'Algo salió mal. Inténtalo de nuevo.', fr: 'Un problème est survenu. Réessaie.', pt: 'Algo deu errado. Tente de novo.', de: 'Etwas ist schiefgelaufen. Bitte versuch es noch mal.', it: 'Qualcosa è andato storto. Riprova.', ja: '問題が発生しました。もう一度お試しください。', ko: '문제가 발생했어요. 다시 시도해 주세요.', zh: '出了点问题，请重试。' },
    'You’re on the Dispatch. Talk soon.': { es: 'Ya estás en The Dispatch. Hablamos pronto.', fr: 'Tu es inscrit à The Dispatch. À très vite.', pt: 'Você está no The Dispatch. Até logo.', de: 'Du bist bei The Dispatch dabei. Bis bald.', it: 'Sei su The Dispatch. A presto.', ja: 'The Dispatchに登録しました。またすぐに。', ko: 'The Dispatch 구독 완료. 곧 만나요.', zh: '你已订阅 The Dispatch，回头见。' },
    'You’re on the list.': { es: 'Estás en la lista.', fr: 'Tu es sur la liste.', pt: 'Você está na lista.', de: 'Du stehst auf der Liste.', it: 'Sei in lista.', ja: 'リストに登録しました。', ko: '명단에 올랐어요.', zh: '你已在名单上。' },
    'Signups only work on the deployed site (Cloudflare Pages).': { es: 'Las suscripciones solo funcionan en el sitio publicado (Cloudflare Pages).', fr: 'Les inscriptions ne fonctionnent que sur le site en ligne (Cloudflare Pages).', pt: 'As inscrições só funcionam no site publicado (Cloudflare Pages).', de: 'Anmeldungen funktionieren nur auf der Live-Seite (Cloudflare Pages).', it: 'Le iscrizioni funzionano solo sul sito pubblicato (Cloudflare Pages).', ja: '登録は公開サイト（Cloudflare Pages）でのみ利用できます。', ko: '구독은 배포된 사이트(Cloudflare Pages)에서만 작동해요.', zh: '订阅仅在已部署的网站（Cloudflare Pages）上可用。' },

    /* ---- radio dock ---- */
    'KIOSK Radio player': { es: 'Reproductor de KIOSK Radio', fr: 'Lecteur KIOSK Radio', pt: 'Player da KIOSK Radio', de: 'KIOSK Radio Player', it: 'Player di KIOSK Radio', ja: 'KIOSK Radio プレーヤー', ko: 'KIOSK Radio 플레이어', zh: 'KIOSK Radio 播放器' },
    'Log in to Spotify in this browser for full tracks. Otherwise Spotify plays 30-second previews.': { es: 'Inicia sesión en Spotify en este navegador para escuchar las canciones completas. Si no, Spotify reproduce avances de 30 segundos.', fr: 'Connecte-toi à Spotify dans ce navigateur pour les titres complets. Sinon, Spotify joue des extraits de 30 secondes.', pt: 'Entre no Spotify neste navegador para ouvir as faixas completas. Caso contrário, o Spotify toca prévias de 30 segundos.', de: 'Melde dich in diesem Browser bei Spotify an, um ganze Tracks zu hören. Sonst spielt Spotify 30-Sekunden-Vorschauen.', it: 'Accedi a Spotify in questo browser per i brani completi. Altrimenti Spotify riproduce anteprime di 30 secondi.', ja: 'このブラウザでSpotifyにログインするとフル再生できます。未ログインの場合は30秒のプレビューになります。', ko: '이 브라우저에서 Spotify에 로그인하면 전곡을 들을 수 있어요. 아니면 30초 미리듣기로 재생돼요.', zh: '在此浏览器登录 Spotify 即可收听完整曲目，否则只能播放 30 秒试听。' },
